import {useLayoutEffect,useRef} from 'react';
import {useOwnedAction} from '@/components/nyc-tron/ui/components/shell/useOwnedAction';

/** Document identity for controlled editor tools. Native handles remain outside UI state. */
export interface ScopedControlProps {scope?:string;revision?:string|number;disabledReason?:string}
export function controlIdentity(scope:string,revision:string|number){
 if(!scope.trim()||scope.length>512||typeof revision==='number'&&!Number.isFinite(revision)||typeof revision==='string'&&revision.length>512)throw new RangeError('Invalid control identity');
 return [scope,revision] as const;
}

/** Admit one host operation and invalidate handlers at the committed boundary. */
export function useScopedControl<P>(boundary:string,props:P,disabled=false){
 const action=useOwnedAction(boundary),pending=action.pending!==null;
 const committed=useRef<{boundary:string;props:P;disabled:boolean}|null>(null);
 const admitted=useRef<symbol|null>(null);
 useLayoutEffect(()=>{committed.current={boundary,props,disabled};});
 useLayoutEffect(()=>{admitted.current=null;},[boundary]);
 useLayoutEffect(()=>()=>{committed.current=null;},[]);
 const current=()=>{const p=committed.current;return p&&p.boundary===boundary&&!p.disabled&&!pending&&!admitted.current?p.props:null;};
 const run=(id:string,operation:(props:P,signal:AbortSignal)=>unknown|Promise<unknown>)=>{
  const p=current();if(!p)return;
  const token=Symbol(id);admitted.current=token;
  return action.run(id,signal=>operation(p,signal),undefined,{pendingForAsyncOnly:true}).finally(()=>{if(admitted.current===token)admitted.current=null;});
 };
 const cancel=()=>{if(committed.current?.boundary!==boundary)return false;admitted.current=null;action.cancel();return true;};
 return {current,run,cancel,pending,pendingId:action.pending,error:action.error};
}

import {ErrorMessage} from '@/components/nyc-tron/ui/components/feedback/ErrorMessage';
import {useScopedControl,controlIdentity,type ScopedControlProps} from '@/components/nyc-tron/ui/components/forge/inputs/useScopedControl';
import {useLayoutEffect,useRef,type ReactNode} from "react";
import {Platform,Text,View,type ViewProps} from "react-native";
import {createStore,type StoreApi} from "zustand/vanilla";
import {useStore} from "zustand";
import {joinClasses} from "@/components/nyc-tron/ui/components/styles";
import {keyboardKey} from "@/components/nyc-tron/ui/components/gestures/drag-transport";
import {useLocalPointer} from "@/components/nyc-tron/ui/components/gestures/useLocalPointer";
import {
  NODE_KINDS,PEN_HANDLE_SIZE,PEN_INSERT_TOLERANCE,PEN_NODE_SIZE,PEN_TAP_SLOP,
  closeAvailability,convertNodeKind,hitPath,insertAfterAvailability,isNodeRef,kindAvailability,moveHandle,moveNode,
  nodeAccessibilityLabel,nodeAt,nodeKindLabel,removeAvailability,replaceNode,sampleSegment,segmentControls,segmentCount,
  splitSegment,validateSubpaths,
  type HandleSide,type InsertNodeIntent,type NodeKindIntent,
} from "@/components/nyc-tron/ui/components/forge/vector/pen-node-model";
import {
  IDENTITY_TRANSFORM,availabilityReason,deltaToContent,nudgeDelta,toView,validateTransform,
  type HandleOffset,type NodeKind,type NodeRef,type PathNode,type Point,type Subpath,type ViewTransform,
} from "@/components/nyc-tron/ui/components/forge/vector/vector-types";
import {CanvasKnob,LinePiece,NoticeLine,VectorButton,type CanvasKeyEvent,type DragModifiers} from "@/components/nyc-tron/ui/components/forge/vector/vector-controls";

/** Source contract for hosts that require scoped, focus-preserving canvas edits.
 * Older alpha.4 artifacts omit this marker; availability must be detected at runtime. */
export const PEN_NODE_EDITOR_CAPABILITIES = Object.freeze({
  version: 1 as const,
  scopedInteractions: true as const,
  geometryCancellation: true as const,
  stableGeometryFocus: true as const,
});

/** `setPathNode` intent: replace one node. */
export interface SetPathNodeIntent extends NodeRef {
  readonly node:PathNode;
}
/** `setSubpathClosed` intent. */
export interface SetClosedIntent {
  readonly subpath:number;
  readonly closed:boolean;
}

/** Props for {@linkcode PenNodeEditor}. The path, selection and every edit are owned by the host. */
export interface PenNodeEditorProps extends Omit<ViewProps,"children">,ScopedControlProps {
  /** The path layer's subpaths, in content coordinates. */
  subpaths:readonly Subpath[];
  /** Optional content-coordinate snapping. The host must return finite coordinates. */
  editScope?:string;
  editRevision?:string|number;
  snapPoint?:(point:Point,ref:NodeRef)=>Point;
  snapHandle?:(offset:HandleOffset,node:PathNode,ref:NodeRef)=>HandleOffset;
  /** Overlay size in points; place it over the canvas region the transform maps into. */
  width:number;
  height:number;
  /** Content to view mapping (zoom, pan, layer transform). @default identity */
  transform?:ViewTransform;
  /** The selected node, or `undefined`. */
  selection:NodeRef|undefined;
  onSelectionChange:(ref:NodeRef|undefined)=>void;
  /** The path to draw during a drag; `undefined` when the drag ends or is cancelled. Never persist here. */
  onPreview?:(subpaths:readonly Subpath[]|undefined)=>void;
  /** A node or handle was dragged and released, or nudged by one key press. Maps to `setPathNode`. */
  onSetPathNode:(intent:SetPathNodeIntent,signal?:AbortSignal)=>void|Promise<unknown>;
  /**
   * A tap on the outline or the "Add node" command split a segment. Maps to
   * `insertPathNode` when {@linkcode InsertNodeIntent.neighborsChanged} is false,
   * otherwise `setPathNodes` with {@linkcode InsertNodeIntent.subpaths}.
   */
  onInsertNode:(intent:InsertNodeIntent,signal?:AbortSignal)=>void|Promise<unknown>;
  /** Delete, Backspace or the command removed a node. Maps to `removePathNode`. */
  onRemoveNode:(ref:NodeRef,signal?:AbortSignal)=>void|Promise<unknown>;
  /**
   * The node kind changed. Maps to `setNodeKind`, or to `setPathNode` with
   * {@linkcode NodeKindIntent.node} when {@linkcode NodeKindIntent.handlesChanged}.
   */
  onSetNodeKind:(intent:NodeKindIntent,signal?:AbortSignal)=>void|Promise<unknown>;
  /** The selected node's subpath was closed or opened. Maps to `setSubpathClosed`. */
  onSetClosed:(intent:SetClosedIntent,signal?:AbortSignal)=>void|Promise<unknown>;
  /** Canvas content drawn under the overlay. It never takes touches while the editor is mounted. */
  children?:ReactNode;
  /** Show the node command bar under the overlay. @default true */
  showCommands?:boolean;
  /** @default "Path nodes" */
  label?:string;
  /** Optional override; defaults to the theme's accent token. */
  accentColor?:string;
  className?:string;
  unstyled?:boolean;
}

type Target={kind:"node";ref:NodeRef}|{kind:"handle";ref:NodeRef;side:HandleSide};
type Drag={target:Target;start:readonly Subpath[];node:PathNode;moved:boolean;cancelled:boolean;last?:PathNode};
type Local={preview:readonly Subpath[]|null;notice:string|undefined};
type KeyEvent=CanvasKeyEvent;
// Web only: a drag otherwise selects nearby text. Not a ViewStyle key in RN.
const NO_SELECT=(Platform.OS==="web"?{userSelect:"none"}:{}) as object;
const HINT="Drag a node or handle. Tap the outline to add a node. Hold Alt while dragging a handle to break it.";
const sideLabel=(side:HandleSide)=>side==="in"?"Incoming handle":"Outgoing handle";

/**
 * On-canvas node editor for one path layer (B-21). Draws the path outline,
 * its nodes and the selected node's Bézier handles over the host's canvas.
 * Drag a node to move it; drag a handle to reshape (smooth keeps the handles
 * collinear, symmetric mirrors their length, Alt breaks them into a corner).
 * Tapping the outline splits the segment there without changing its shape.
 * Arrow keys nudge the focused node or handle by 1 unit (Shift: 10), Delete
 * removes the node, Escape cancels a drag. Every release or key press commits
 * once; previews go through `onPreview`.
 *
 * Curves are drawn as short straight pieces sampled from the exact Bézier, so
 * the overlay needs no SVG dependency; the engine renders the real curve.
 */
export function PenNodeEditor({scope,revision,editScope,editRevision,...props}:PenNodeEditorProps){
 const id=scope??editScope??'path-nodes',version=revision??editRevision??0;
 const owner=JSON.stringify([...controlIdentity(id,version),props.disabledReason,props.width,props.height,props.transform]);
 const guard=useScopedControl(owner,props,props.disabledReason!==undefined);
 // Revision effects discard stale gestures without replacing the focused keyboard target.
 return <PenNodeEditorBody key={id} {...props} editScope={id} editRevision={version} actionError={guard.error} busy={guard.pending}
  onSelectionChange={value=>guard.current()?.onSelectionChange(value)} onPreview={value=>guard.current()?.onPreview?.(value)}
  onSetPathNode={value=>guard.run('onSetPathNode',(host,signal)=>host.onSetPathNode(value,signal))}
  onInsertNode={value=>guard.run('onInsertNode',(host,signal)=>host.onInsertNode(value,signal))}
  onRemoveNode={value=>guard.run('onRemoveNode',(host,signal)=>host.onRemoveNode(value,signal))}
  onSetNodeKind={value=>guard.run('onSetNodeKind',(host,signal)=>host.onSetNodeKind(value,signal))}
  onSetClosed={value=>guard.run('onSetClosed',(host,signal)=>host.onSetClosed(value,signal))}
/>;
}
function PenNodeEditorBody({
  actionError=null,busy=false,disabledReason,
  subpaths,snapPoint,snapHandle,editScope,editRevision,width,height,transform=IDENTITY_TRANSFORM,selection,onSelectionChange,onPreview,onSetPathNode,
  onInsertNode,onRemoveNode,onSetNodeKind,onSetClosed,children,showCommands=true,label="Path nodes",
  accentColor,className,unstyled=false,style,...rest
}:PenNodeEditorProps&{actionError?:string|null;busy?:boolean}){
  validateSubpaths(subpaths);
  validateTransform(transform);
  if(![width,height].every(Number.isFinite)||width<=0||height<=0)throw new RangeError("Invalid editor size");
  const latest=useRef({subpaths,snapPoint,snapHandle,transform,selection,onSelectionChange,onPreview,onSetPathNode,onInsertNode,
    onRemoveNode,onSetNodeKind,onSetClosed});
  latest.current={subpaths,snapPoint,snapHandle,transform,selection,onSelectionChange,onPreview,onSetPathNode,onInsertNode,
    onRemoveNode,onSetNodeKind,onSetClosed};
  const local=useRef<StoreApi<Local>|null>(null);
  if(!local.current)local.current=createStore<Local>(()=>({preview:null,notice:undefined}));
  const store=local.current;
  const preview=useStore(store,s=>s.preview);
  const notice=useStore(store,s=>s.notice);
  const drag=useRef<Drag|null>(null);
  const altHeld=useRef(false);
  const pressAt=useRef<Point|null>(null);
  const shown=preview??subpaths;
  const selected=isNodeRef(shown,selection)?selection:undefined;
  const styled=!unstyled;

  const clearPreview=()=>{
    if(store.getState().preview===null)return;
    store.setState({preview:null});
    latest.current.onPreview?.(undefined);
  };
  useLayoutEffect(()=>()=>{drag.current=null;pressAt.current=null;if(store.getState().preview!==null){store.setState({preview:null});latest.current.onPreview?.(undefined);}},[store,editScope,editRevision]);
  const geometryBoundary=JSON.stringify([subpaths,transform,width,height,disabledReason,busy]);
  useLayoutEffect(()=>{drag.current=null;pressAt.current=null;clearPreview();},[geometryBoundary]);
  const cancelDrag=()=>{
    const d=drag.current;
    if(!d)return false;
    d.cancelled=true;
    clearPreview();
    return true;
  };
  const begin=(target:Target)=>{
    if(drag.current){cancelDrag();return;}
    const p=latest.current;
    drag.current={target,start:p.subpaths,node:nodeAt(p.subpaths,target.ref),moved:false,cancelled:false};
    const sel=p.selection;
    if(!sel||sel.subpath!==target.ref.subpath||sel.index!==target.ref.index)p.onSelectionChange(target.ref);
    store.setState({notice:undefined});
  };
  const snappedNode=(node:PathNode,ref:NodeRef):PathNode=>{
    const point=latest.current.snapPoint?.({x:node.x,y:node.y},ref);
    if(!point)return node;
    if(![point.x,point.y].every(Number.isFinite))throw new RangeError("Snapped point must be finite");
    return {...node,x:point.x,y:point.y};
  };
  const snappedHandle=(offset:HandleOffset,node:PathNode,ref:NodeRef):HandleOffset=>{
    const next=latest.current.snapHandle?.(offset,node,ref)??offset;
    if(next.length!==2||!next.every(Number.isFinite))throw new RangeError("Snapped handle must be finite");
    return next;
  };
  const dragTo=(dx:number,dy:number,mods:DragModifiers)=>{
    const d=drag.current;
    if(!d||d.cancelled)return;
    if(!d.moved&&Math.hypot(dx,dy)<PEN_TAP_SLOP)return;
    d.moved=true;
    const c=deltaToContent(latest.current.transform,dx,dy);
    let node:PathNode;
    if(d.target.kind==="node")node=snappedNode(moveNode(d.node,c.x,c.y),d.target.ref);
    else{
      const h=d.node[d.target.side] as HandleOffset;
      node=moveHandle(d.node,d.target.side,snappedHandle([h[0]+c.x,h[1]+c.y],d.node,d.target.ref),mods.alt||altHeld.current);
    }
    d.last=node;
    const next=replaceNode(d.start,d.target.ref,node);
    store.setState({preview:next});
    latest.current.onPreview?.(next);
  };
  const release=()=>{
    const d=drag.current;
    drag.current=null;
    if(!d||d.cancelled)return;
    if(!d.moved||!d.last){clearPreview();return;}
    // Clear before the commit so the host's next render shows its own value.
    clearPreview();
    latest.current.onSetPathNode({subpath:d.target.ref.subpath,index:d.target.ref.index,node:d.last});
  };

  const block=(reason:string)=>store.setState({notice:reason});
  const removeSelected=(at?:NodeRef)=>{
    const p=latest.current;
    const ref=at??p.selection;
    const reason=availabilityReason(removeAvailability(p.subpaths,ref));
    if(reason!==undefined||!ref){block(reason??"");return;}
    store.setState({notice:undefined});
    p.onRemoveNode({subpath:ref.subpath,index:ref.index});
    // Keep a selection so Delete can be pressed again: the node that took this index, else the new last one.
    const left=p.subpaths[ref.subpath]!.nodes.length-1;
    p.onSelectionChange({subpath:ref.subpath,index:Math.min(ref.index,left-1)});
  };
  const insertAfter=(at?:NodeRef)=>{
    const p=latest.current;
    const ref=at??p.selection;
    const reason=availabilityReason(insertAfterAvailability(p.subpaths,ref));
    if(reason!==undefined||!ref){block(reason??"");return;}
    const intent=splitSegment(p.subpaths,ref.subpath,ref.index,0.5);
    store.setState({notice:undefined});
    p.onInsertNode(intent);
    p.onSelectionChange({subpath:intent.subpath,index:intent.index});
  };
  const setKind=(kind:NodeKind,at?:NodeRef)=>{
    const p=latest.current;
    const ref=at??p.selection;
    const reason=availabilityReason(kindAvailability(p.subpaths,ref));
    if(reason!==undefined||!ref){block(reason??"");return;}
    if(nodeAt(p.subpaths,ref).kind===kind)return;
    store.setState({notice:undefined});
    p.onSetNodeKind(convertNodeKind(p.subpaths,ref,kind));
  };
  const toggleClosed=()=>{
    const p=latest.current;
    const reason=availabilityReason(closeAvailability(p.subpaths,p.selection));
    if(reason!==undefined){block(reason);return;}
    const sp=p.subpaths[p.selection!.subpath]!;
    store.setState({notice:undefined});
    p.onSetClosed({subpath:p.selection!.subpath,closed:!sp.closed});
  };
  const nudge=(target:Target,delta:Point,alt:boolean)=>{
    const p=latest.current;
    const node=nodeAt(p.subpaths,target.ref);
    let next:PathNode;
    if(target.kind==="node")next=snappedNode(moveNode(node,delta.x,delta.y),target.ref);
    else{
      const h=node[target.side];
      if(!h)return;
      next=moveHandle(node,target.side,snappedHandle([h[0]+delta.x,h[1]+delta.y],node,target.ref),alt);
    }
    p.onSetPathNode({subpath:target.ref.subpath,index:target.ref.index,node:next});
  };
  const onKnobKey=(target:Target)=>(event:KeyEvent)=>{
    const key=keyboardKey(event);
    const shift=event.shiftKey??event.nativeEvent?.shiftKey??false;
    const alt=event.altKey??event.nativeEvent?.altKey??false;
    if(key==="Escape"){
      if(!cancelDrag()&&target.kind==="node")latest.current.onSelectionChange(undefined);
      event.preventDefault?.();
      return;
    }
    const delta=nudgeDelta(key,shift);
    if(delta){event.preventDefault?.();nudge(target,delta,alt);return;}
    if(target.kind==="node"&&(key==="Delete"||key==="Backspace")){event.preventDefault?.();removeSelected(target.ref);}
  };
  const onRootKey=(event:KeyEvent)=>{
    const key=keyboardKey(event);
    if(key==="Alt")altHeld.current=true;
    else if(key==="Escape"&&drag.current){cancelDrag();event.preventDefault?.();}
  };
  const onRootKeyUp=(event:KeyEvent)=>{if(keyboardKey(event)==="Alt")altHeld.current=false;};

  const canvasHandlers=useLocalPointer({
    onBegin:point=>{pressAt.current=point;},
    onMove:()=>{},
    onRelease:point=>{
      const start=pressAt.current;
      pressAt.current=null;
      if(!start||Math.hypot(point.x-start.x,point.y-start.y)>PEN_TAP_SLOP*2)return;
      const p=latest.current;
      const hit=hitPath(p.subpaths,point,PEN_INSERT_TOLERANCE,q=>toView(p.transform,q));
      if(hit&&hit.t>0.001&&hit.t<0.999){
        const intent=splitSegment(p.subpaths,hit.subpath,hit.segment,hit.t);
        store.setState({notice:undefined});
        p.onInsertNode(intent);
        p.onSelectionChange({subpath:intent.subpath,index:intent.index});
      }else if(p.selection)p.onSelectionChange(undefined);
    },
    onCancel:()=>{pressAt.current=null;},
  });

  const view=(q:Point)=>toView(transform,q);
  const accentLine=joinClasses(styled&&!accentColor&&"bg-accent");
  const outline=shown.flatMap((sp,si)=>Array.from({length:segmentCount(sp)},(_,s)=>{
    const pts=sampleSegment(segmentControls(sp,s)).map(view);
    return pts.slice(1).map((pt,i)=><LinePiece key={`o${si}-${s}-${i}`} from={pts[i]!} to={pt} thickness={1.5}
      className={accentLine} color={accentColor}/>);
  }));
  const selNode=selected?nodeAt(shown,selected):undefined;
  const handles=selected&&selNode?(["in","out"] as const).flatMap(side=>{
    const h=selNode[side];
    if(!h)return [];
    const at=view({x:selNode.x,y:selNode.y}),tip=view({x:selNode.x+h[0],y:selNode.y+h[1]});
    const target:Target={kind:"handle",ref:selected,side};
    return [<LinePiece key={"l"+side} from={at} to={tip} thickness={1} className={joinClasses(styled&&"bg-text-muted")}/>,
      <CanvasKnob key={"h"+side} at={tip} selected={false} styled={styled} zIndex={2}
        testID={"pen-handle-"+side}
        label={`${sideLabel(side)} of node ${selected.index+1}, ${Math.round(h[0]*10)/10} by ${Math.round(h[1]*10)/10}`}
        hint="Drag, or use arrow keys, to reshape the curve. Hold Alt to break a smooth node."
        onBegin={()=>begin(target)} onMove={dragTo} onRelease={release} onCancel={cancelDrag}
        onKeyDown={onKnobKey(target)}
        onAction={name=>{const d=ACTION_DELTA[name];if(d)nudge(target,d,false);}}
        actions={MOVE_ACTIONS}>
        <KnobGlyph shape="handle" selected={false} styled={styled} accentColor={accentColor}/>
      </CanvasKnob>];
  }):[];

  const selSub=selected?shown[selected.subpath]:undefined;
  return <View {...rest} {...{onKeyDown:onRootKey,onKeyUp:onRootKeyUp,className:joinClasses("gap-2",className)}}
    style={[{alignSelf:"flex-start",maxWidth:"100%"},style]}>
    <ErrorMessage message={actionError??undefined} unstyled={unstyled}/>
    {disabledReason||busy?<Text accessibilityLiveRegion="polite">{disabledReason??"Applying path change"}</Text>:null}
    <View {...canvasHandlers} accessibilityLabel={label} testID="pen-canvas"
      {...{className:joinClasses("overflow-hidden",styled&&"rounded-control border border-border")}}
      // Canvas geometry stays left to right in RTL documents.
      style={{width,height,position:"relative",direction:"ltr",...NO_SELECT}}>
      <View pointerEvents="none" style={{position:"absolute",left:0,top:0,width,height}}>{children}</View>
      {outline}
      {handles}
      {shown.flatMap((sp,si)=>sp.nodes.map((node,i)=>{
        const ref={subpath:si,index:i};
        const target:Target={kind:"node",ref};
        const isSel=selected?.subpath===si&&selected.index===i;
        return <CanvasKnob key={`n${si}-${i}`} at={view(node)} selected={isSel} styled={styled}
          testID={`pen-node-${si}-${i}`}
          label={nodeAccessibilityLabel(shown,ref)}
          hint="Drag or use arrow keys to move. Delete removes it."
          onFocus={()=>{if(!isSel)latest.current.onSelectionChange(ref);}}
          onBegin={()=>begin(target)} onMove={dragTo} onRelease={release} onCancel={cancelDrag}
          onKeyDown={onKnobKey(target)}
          actions={NODE_ACTIONS}
          onAction={name=>{
            if(name==="activate"){latest.current.onSelectionChange(ref);return;}
            latest.current.onSelectionChange(ref);
            const d=ACTION_DELTA[name];
            if(d){nudge(target,d,false);return;}
            if(name==="insertAfter")insertAfter(ref);
            else if(name==="remove")removeSelected(ref);
            else if(name==="cycleKind"){
              const kinds=NODE_KINDS.map(k=>k.value);
              setKind(kinds[(kinds.indexOf(node.kind)+1)%kinds.length]!,ref);
            }
          }}>
          <KnobGlyph shape={node.kind} selected={isSel} styled={styled} accentColor={accentColor}/>
        </CanvasKnob>;
      }))}
    </View>
    {showCommands?<View accessibilityRole="toolbar" aria-label="Node commands"
      style={{flexDirection:"row",flexWrap:"wrap",gap:6,maxWidth:Math.max(width,320)}}>
      <View role="radiogroup" aria-label="Node kind" style={{flexDirection:"row",gap:6}}>
        {NODE_KINDS.map(k=><VectorButton key={k.value} role="radio" label={k.label} styled={styled}
          checked={selNode?.kind===k.value}
          reason={availabilityReason(kindAvailability(shown,selected))}
          onBlocked={block} onPress={()=>setKind(k.value)}/>)}
      </View>
      <VectorButton label="Add node" styled={styled} onBlocked={block} onPress={()=>insertAfter()}
        reason={availabilityReason(insertAfterAvailability(shown,selected))}/>
      <VectorButton label="Delete node" styled={styled} onBlocked={block} onPress={()=>removeSelected()}
        reason={availabilityReason(removeAvailability(shown,selected))}/>
      <VectorButton label={selSub?.closed?"Open path":"Close path"} styled={styled} onBlocked={block} onPress={toggleClosed}
        reason={availabilityReason(closeAvailability(shown,selected))}/>
    </View>:null}
    {showCommands?<NoticeLine text={notice??(selNode?`${nodeKindLabel(selNode.kind)} node selected. ${HINT}`:HINT)}
      styled={styled} testID="pen-notice"/>:null}
  </View>;
}

const ACTION_DELTA:Record<string,Point|undefined>={
  moveLeft:{x:-1,y:0},moveRight:{x:1,y:0},moveUp:{x:0,y:-1},moveDown:{x:0,y:1},
};
const MOVE_ACTIONS=[
  {name:"moveLeft",label:"Move left"},{name:"moveRight",label:"Move right"},
  {name:"moveUp",label:"Move up"},{name:"moveDown",label:"Move down"},
];
const NODE_ACTIONS=[
  {name:"activate",label:"Select"},...MOVE_ACTIONS,
  {name:"cycleKind",label:"Change node kind"},{name:"insertAfter",label:"Add node after"},{name:"remove",label:"Delete node"},
];

/** Node and handle marker: square corner, round smooth, diamond symmetric, small round handle; filled when selected. */
function KnobGlyph({shape,selected,styled,accentColor}:{shape:NodeKind|"handle";selected:boolean;styled:boolean;accentColor:string|undefined}){
  const size=shape==="handle"?PEN_HANDLE_SIZE:PEN_NODE_SIZE;
  const fill=selected?joinClasses(styled&&!accentColor&&"bg-accent"):joinClasses(styled&&"bg-surface-raised");
  return <View pointerEvents="none" {...{className:joinClasses(fill,styled&&!accentColor&&"border-accent")}}
    style={{width:size,height:size,borderWidth:2,...(accentColor?{borderColor:accentColor}:null),
      ...(selected&&accentColor?{backgroundColor:accentColor}:null),
      borderRadius:shape==="smooth"||shape==="handle"?size/2:shape==="corner"?1:0,
      transform:shape==="symmetric"?[{rotate:"45deg"}]:undefined}}/>;
}

/**
 * Small pieces shared by the vector-tools components: a straight overlay line
 * drawn as a rotated view (the PatchGraph wire technique, since the package has
 * no SVG dependency), and a command button that stays pressable while
 * unavailable so it can say why in the cluster's notice line.
 */
import {useRef,type ReactNode} from "react";
import {PanResponder,Pressable,Text,View,type GestureResponderEvent} from "react-native";
import {createCanvasResponder} from "@/components/nyc-tron/ui/components/gestures/canvas-responder";
import {joinClasses} from "@/components/nyc-tron/ui/components/styles";
import type {Point} from "@/components/nyc-tron/ui/components/forge/vector/vector-types";

/** Every vector-tools control target is at least this many points square. */
export const VECTOR_TOUCH_TARGET=44;

/** A straight line between two view points, never a touch target. */
export function LinePiece({from,to,thickness=2,className,color,opacity=1}:{
  from:Point;to:Point;thickness?:number;className?:string|undefined;color?:string|undefined;opacity?:number;
}){
  const dx=to.x-from.x,dy=to.y-from.y,len=Math.hypot(dx,dy);
  if(len<0.01)return null;
  return <View pointerEvents="none" {...{className}}
    style={{position:"absolute",left:(from.x+to.x-len)/2,top:(from.y+to.y)/2-thickness/2,width:len,height:thickness,
      opacity,...(color?{backgroundColor:color}:null),transform:[{rotate:Math.atan2(dy,dx)*180/Math.PI+"deg"}]}}/>;
}

/**
 * Command button for the vector tools. When `reason` is set the button reads
 * as unavailable but still takes the press and reports the reason instead of
 * running, so nothing is silently dead.
 */
export function VectorButton({label,reason,onPress,onBlocked,role="button",checked,styled,children,testID}:{
  label:string;reason?:string|undefined;onPress:()=>void;onBlocked:(reason:string)=>void;
  role?:"button"|"radio"|"switch";checked?:boolean;styled:boolean;children?:ReactNode;testID?:string;
}){
  const disabled=reason!==undefined;
  const on=checked===true;
  // React Native Web's Pressable overwrites aria-disabled with its own
  // `disabled` prop, which would swallow the press; "unavailable" in the name
  // carries the state on web and accessibilityState carries it natively.
  return <Pressable role={role} aria-label={disabled?label+", unavailable":label} testID={testID}
    aria-checked={role==="button"?undefined:on} accessibilityState={{disabled,...(role==="button"?{}:{checked:on})}}
    accessibilityHint={reason}
    onPress={()=>{if(reason!==undefined)onBlocked(reason);else onPress();}}
    {...{className:joinClasses(styled&&"rounded-control border focus-visible:ring-2 focus-visible:ring-focus",
      styled&&(on?"border-primary bg-primary":"border-border bg-surface-raised"))}}
    style={{minWidth:VECTOR_TOUCH_TARGET,minHeight:VECTOR_TOUCH_TARGET,paddingHorizontal:12,
      flexDirection:"row",alignItems:"center",justifyContent:"center",gap:6,opacity:disabled?0.5:1}}>
    {children}
    <Text numberOfLines={1} {...{className:joinClasses(styled&&(on?"text-on-primary":"text-text"))}}
      style={{fontSize:13,fontWeight:on?"700":"500"}}>{label}</Text>
  </Pressable>;
}

/** Polite status line: hints, and the reason an unavailable command did not run. */
export function NoticeLine({text,styled,testID}:{text:string|undefined;styled:boolean;testID?:string}){
  return <Text accessibilityLiveRegion="polite" aria-live="polite" testID={testID}
    {...{className:joinClasses(styled&&"text-text-muted text-xs")}} style={{minHeight:18}}>{text??""}</Text>;
}

/** Group heading inside an inspector or bar. */
export function GroupLabel({children,styled,nativeID}:{children:string;styled:boolean;nativeID?:string}){
  return <Text accessibilityRole="header" nativeID={nativeID}
    {...{className:joinClasses(styled&&"text-text text-xs font-semibold")}}>{children}</Text>;
}

/** Modifier keys seen during a canvas drag. React Native Web reports Shift; Alt comes from key tracking. */
export interface DragModifiers {
  readonly alt:boolean;
  readonly shift:boolean;
  readonly ctrl?:boolean;
  readonly meta?:boolean;
}
/** Keyboard event shape on web (`key`, modifiers) and native (`nativeEvent`). */
export type CanvasKeyEvent={
  key?:string;shiftKey?:boolean;altKey?:boolean;preventDefault?:()=>void;
  nativeEvent?:{key?:string;shiftKey?:boolean;altKey?:boolean};
};
/** Props for {@linkcode CanvasKnob}. */
export interface CanvasKnobProps {
  /** Centre in overlay points. */
  at:Point;
  testID:string;
  label:string;
  hint:string;
  selected:boolean;
  actions:readonly {name:string;label:string}[];
  onAction:(name:string)=>void;
  onKeyDown:(event:CanvasKeyEvent)=>void;
  onFocus?:()=>void;
  onBegin:(modifiers:DragModifiers)=>void;
  /** View-space travel since the press. Preview only. */
  onMove:(dx:number,dy:number,modifiers:DragModifiers)=>void;
  onRelease:()=>void;
  onCancel:()=>void;
  /** Drawn marker, centred in the 44pt target. */
  children:ReactNode;
  zIndex?:number;
  styled:boolean;
}
/**
 * A 44pt draggable, focusable target centred on an on-canvas point. A second
 * pointer or OS termination cancels; a parent scroll view cannot steal it.
 */
export function CanvasKnob(props:CanvasKnobProps){
  const {at,testID,label,hint,selected,actions,onAction,onKeyDown,onFocus,children,zIndex=1,styled}=props;
  const latest=useRef(props);
  latest.current=props;
  const pan=useRef<ReturnType<typeof PanResponder.create>|null>(null);
  if(!pan.current)pan.current=createCanvasResponder({
    onStartShouldSetPanResponder:e=>(e.nativeEvent.touches?.length??1)<=1,
    onMoveShouldSetPanResponder:()=>true,
    onPanResponderGrant:e=>{const n=e.nativeEvent as {altKey?:boolean;shiftKey?:boolean;ctrlKey?:boolean;metaKey?:boolean};latest.current.onBegin({alt:n.altKey===true,shift:n.shiftKey===true,ctrl:n.ctrlKey===true,meta:n.metaKey===true});},
    onPanResponderMove:(e:GestureResponderEvent,g)=>{
      if(g.numberActiveTouches>1){latest.current.onCancel();return;}
      const n=e.nativeEvent as {altKey?:boolean;shiftKey?:boolean};
      latest.current.onMove(g.dx,g.dy,{alt:n.altKey===true,shift:n.shiftKey===true});
    },
    onPanResponderRelease:()=>latest.current.onRelease(),
    onPanResponderTerminationRequest:()=>false,
    onPanResponderTerminate:()=>latest.current.onCancel(),
  });
  return <View {...pan.current.panHandlers} accessible testID={testID}
    accessibilityRole="button" accessibilityLabel={label} accessibilityHint={hint}
    accessibilityState={{selected}} accessibilityActions={actions}
    onAccessibilityAction={e=>onAction(e.nativeEvent.actionName)}
    {...{onKeyDown,focusable:true,onFocus,
      className:joinClasses(styled&&"rounded-control focus-visible:ring-2 focus-visible:ring-focus")}}
    style={{position:"absolute",left:at.x-VECTOR_TOUCH_TARGET/2,top:at.y-VECTOR_TOUCH_TARGET/2,
      width:VECTOR_TOUCH_TARGET,height:VECTOR_TOUCH_TARGET,alignItems:"center",justifyContent:"center",zIndex}}>
    {children}
  </View>;
}

import {PanResponder,Platform,type GestureResponderEvent,type PanResponderCallbacks,type PanResponderGestureState} from "react-native";

type Pointer = {
  pointerId:number;button:number;isPrimary?:boolean;clientX:number;clientY:number;pageX:number;pageY:number;
  altKey?:boolean;shiftKey?:boolean;ctrlKey?:boolean;metaKey?:boolean;
};
type Surface = {
  focus?(options?:{preventScroll?:boolean}):void;
  getBoundingClientRect():{left:number;top:number};
  setPointerCapture(id:number):void;
  releasePointerCapture(id:number):void;
  hasPointerCapture(id:number):boolean;
};
type PointerEvent = {
  nativeEvent:Pointer;currentTarget:Surface;
  preventDefault():void;
};

/**
 * Canvas gesture transport. Native keeps PanResponder. Web uses actual pointer
 * capture because RN Web deliberately excludes Alt/Ctrl mouse presses from its
 * responder system, while canvas tools need those modifiers for editing.
 * Pointer positions are normalized to the same local/page coordinate contract.
 */
export function createCanvasResponder(config:PanResponderCallbacks):ReturnType<typeof PanResponder.create>{
  if(Platform.OS!=="web")return PanResponder.create(config);
  let active:{id:number;surface:Surface;x:number;y:number;pageX:number;pageY:number}|undefined;
  const normalize=(event:PointerEvent):[GestureResponderEvent,PanResponderGestureState]=>{
    const n=event.nativeEvent,rect=event.currentTarget.getBoundingClientRect();
    const start=active??{x:n.clientX,y:n.clientY,pageX:n.pageX,pageY:n.pageY};
    const nativeEvent={...n,locationX:n.clientX-rect.left,locationY:n.clientY-rect.top,
      altKey:n.altKey,shiftKey:n.shiftKey,ctrlKey:n.ctrlKey,metaKey:n.metaKey,
      pageX:n.pageX,pageY:n.pageY,touches:[{pageX:n.pageX,pageY:n.pageY}]};
    const gesture={stateID:n.pointerId,moveX:n.pageX,moveY:n.pageY,x0:start.pageX,y0:start.pageY,
      dx:n.clientX-start.x,dy:n.clientY-start.y,vx:0,vy:0,numberActiveTouches:1};
    // These are event/coordinate adapters only; no native resource is fabricated.
    return [{nativeEvent,preventDefault:()=>event.preventDefault()} as unknown as GestureResponderEvent,gesture as PanResponderGestureState];
  };
  const release=()=>{
    const owner=active;active=undefined;
    if(owner?.surface.hasPointerCapture(owner.id))owner.surface.releasePointerCapture(owner.id);
  };
  const handlers={
    onPointerDown(event:PointerEvent){
      const n=event.nativeEvent;
      if(active){const args=normalize(event);args[1].numberActiveTouches=2;try{config.onPanResponderTerminate?.(...args);}finally{release();}return;}
      if(n.button!==0||n.isPrimary===false)return;
      const args=normalize(event);
      if(config.onStartShouldSetPanResponder?.(...args)===false)return;
      event.preventDefault();
      event.currentTarget.focus?.({preventScroll:true});
      active={id:n.pointerId,surface:event.currentTarget,x:n.clientX,y:n.clientY,pageX:n.pageX,pageY:n.pageY};
      event.currentTarget.setPointerCapture(n.pointerId);
      config.onPanResponderGrant?.(...normalize(event));
    },
    onPointerMove(event:PointerEvent){if(active?.id===event.nativeEvent.pointerId)config.onPanResponderMove?.(...normalize(event));},
    onPointerUp(event:PointerEvent){
      if(active?.id!==event.nativeEvent.pointerId)return;
      try{config.onPanResponderRelease?.(...normalize(event));}finally{release();}
    },
    onPointerCancel(event:PointerEvent){
      if(active?.id!==event.nativeEvent.pointerId)return;
      try{config.onPanResponderTerminate?.(...normalize(event));}finally{release();}
    },
    onLostPointerCapture(event:PointerEvent){
      if(active?.id!==event.nativeEvent.pointerId)return;
      try{config.onPanResponderTerminate?.(...normalize(event));}finally{release();}
    },
  };
  return {panHandlers:handlers as unknown as ReturnType<typeof PanResponder.create>["panHandlers"],getInteractionHandle:()=>undefined};
}

import {createContext,useRef} from 'react';
/** Invalidate ephemeral gestures without remounting focused controls or product state. */
export const EditorInteractionScope=createContext<string|null>(null);
let nextInstance=0;
/** Compare cached document signatures by identity without reserializing a whole
 * timeline on every playback tick or nesting its data in child scope strings. */
export function useEditorBoundary(parts:readonly unknown[]):string{
 const ref=useRef<{id:number;version:number;parts:readonly unknown[]}|null>(null);
 ref.current??={id:++nextInstance,version:0,parts:[]};
 const current=ref.current;
 if(parts.length!==current.parts.length||parts.some((part,index)=>!Object.is(part,current.parts[index]))){current.parts=[...parts];current.version++;}
 return current.id+':'+current.version;
}

import type {GestureResponderEvent,PanResponderCallbacks} from "react-native";

/** A point in the responder view's own coordinates (0,0 is its top-left corner). */
export interface LocalPoint {
  readonly x:number;
  readonly y:number;
  /**
   * Touch or stylus force 0..1 when the platform reports one (iOS touches and
   * Apple Pencil, Android styluses). Absent for mice and for touch screens
   * that report no force.
   */
  readonly pressure?:number;
}
/**
 * Callbacks for {@linkcode localPointerConfig}. Unlike `DragTransport`, which reports
 * page coordinates, these report points inside the view, for controls that map a
 * position to a value (a color disc, a seek bar, a clip edge).
 */
export interface LocalPointerHandlers {
  readonly disabled?:boolean;
  onBegin(point:LocalPoint):void;
  onMove(point:LocalPoint):void;
  onRelease(point:LocalPoint):void;
  /** OS termination, or a second pointer when {@linkcode LocalPointerHandlers.onPinch} is absent. */
  onCancel():void;
  /**
   * Two-pointer pinch. `scale` is the current pointer distance over the distance when
   * the second pointer landed; `center` is their midpoint. Once a pinch starts, the
   * gesture ends with {@linkcode LocalPointerHandlers.onPinchEnd} instead of a release.
   */
  onPinch?(scale:number,center:LocalPoint):void;
  onPinchEnd?():void;
}

type Latest={readonly current:LocalPointerHandlers};

const withForce=(point:{x:number;y:number},force:number|undefined):LocalPoint=>
  typeof force==="number"&&Number.isFinite(force)&&force>0?{...point,pressure:Math.min(1,force)}:point;
type Touch={readonly pageX:number;readonly pageY:number};

/**
 * PanResponder callbacks that report view-local points. The grant point is
 * `locationX/Y`, which is relative to the touched view, so every child of the
 * responder view must set `pointerEvents="none"`. Later points add the page-space
 * travel to the grant point; `locationX` on a move would be measured from whatever
 * view the pointer is over.
 */
export function localPointerConfig(latest:Latest):PanResponderCallbacks{
  let origin={x:0,y:0,pageX:0,pageY:0};
  let pinch:{distance:number}|undefined;
  let live=false;
  const local=(pageX:number,pageY:number,force?:number):LocalPoint=>withForce({x:origin.x+pageX-origin.pageX,y:origin.y+pageY-origin.pageY},force);
  const touchesOf=(event:GestureResponderEvent):readonly Touch[]=>event.nativeEvent.touches??[];
  const end=()=>{live=false;pinch=undefined;};
  return {
    onStartShouldSetPanResponder:()=>!latest.current.disabled,
    onMoveShouldSetPanResponder:()=>!latest.current.disabled,
    onPanResponderGrant:event=>{
      const n=event.nativeEvent;
      origin={x:n.locationX,y:n.locationY,pageX:n.pageX,pageY:n.pageY};
      pinch=undefined;
      live=true;
      latest.current.onBegin(withForce({x:n.locationX,y:n.locationY},n.force));
    },
    onPanResponderMove:event=>{
      if(!live)return;
      const touches=touchesOf(event);
      if(touches.length>=2){
        const handlers=latest.current;
        if(!handlers.onPinch){end();handlers.onCancel();return;}
        const [a,b]=touches as [Touch,Touch];
        const distance=Math.hypot(b.pageX-a.pageX,b.pageY-a.pageY);
        if(!pinch){
          // The one-pointer gesture that started this is abandoned, not committed.
          handlers.onCancel();
          pinch={distance:Math.max(distance,1)};
        }
        handlers.onPinch(distance/pinch.distance,local((a.pageX+b.pageX)/2,(a.pageY+b.pageY)/2));
        return;
      }
      if(pinch)return;
      latest.current.onMove(local(event.nativeEvent.pageX,event.nativeEvent.pageY,event.nativeEvent.force));
    },
    onPanResponderRelease:event=>{
      if(!live)return;
      const pinched=pinch!==undefined;
      end();
      if(pinched)latest.current.onPinchEnd?.();
      else latest.current.onRelease(local(event.nativeEvent.pageX,event.nativeEvent.pageY));
    },
    // A parent ScrollView must not take a granted drag; the OS still can.
    onPanResponderTerminationRequest:()=>false,
    onPanResponderTerminate:()=>{
      if(!live)return;
      const pinched=pinch!==undefined;
      end();
      if(pinched)latest.current.onPinchEnd?.();
      else latest.current.onCancel();
    },
    onShouldBlockNativeResponder:()=>true,
  };
}

import {useContext,useLayoutEffect,useMemo,useRef} from "react";
import {PanResponder,type GestureResponderEvent,type GestureResponderHandlers,type PanResponderGestureState,type PanResponderCallbacks} from "react-native";
import {localPointerConfig,type LocalPointerHandlers} from "@/components/nyc-tron/ui/components/gestures/local-pointer";
import {EditorInteractionScope} from '@/components/nyc-tron/ui/components/gestures/editor-interaction-scope';

/**
 * Responder handlers for one view, built once and fed the latest callbacks on
 * every event. Spread the result on the view that defines the local coordinate
 * space; see {@linkcode localPointerConfig} for the `pointerEvents` rule.
 */
export function useLocalPointer(handlers:LocalPointerHandlers):GestureResponderHandlers{
  const scope=useContext(EditorInteractionScope);
  const latest=useRef(handlers);
  useLayoutEffect(()=>{latest.current=handlers;});
  const owner=useRef<{active:boolean;blocked:boolean;last:[GestureResponderEvent,PanResponderGestureState]|null}>({active:false,blocked:false,last:null});
  const config=useMemo<PanResponderCallbacks>(()=>localPointerConfig(latest),[]);
  const cancel=()=>{const s=owner.current;owner.current={active:false,blocked:true,last:null};if(s.active&&s.last)config.onPanResponderTerminate?.(...s.last);};
  useLayoutEffect(()=>{if(scope!==null)cancel();return()=>{if(scope!==null)cancel();};},[scope]);
  return useMemo(()=>PanResponder.create({
    ...config,
    onStartShouldSetPanResponder:(...args)=>{owner.current.blocked=false;return config.onStartShouldSetPanResponder?.(...args)??false;},
    onMoveShouldSetPanResponder:(...args)=>!owner.current.blocked&&(config.onMoveShouldSetPanResponder?.(...args)??false),
    onPanResponderGrant:(...args)=>{owner.current={active:true,blocked:false,last:args};config.onPanResponderGrant?.(...args);},
    onPanResponderMove:(...args)=>{if(!owner.current.active)return;owner.current.last=args;config.onPanResponderMove?.(...args);},
    onPanResponderRelease:(...args)=>{if(!owner.current.active)return;owner.current.active=false;owner.current.last=null;config.onPanResponderRelease?.(...args);},
    onPanResponderTerminate:(...args)=>{if(!owner.current.active)return;owner.current.active=false;owner.current.last=null;config.onPanResponderTerminate?.(...args);},
  }).panHandlers,[config]);
}

import { createStore } from "zustand/vanilla";

/** UI request state. Abort controllers stay in the owner's closure. */
export interface ActionState { readonly pending: string | null; readonly error: string | null }
export function createActionOwner(currentScope: () => string) {
  const store = createStore<ActionState>(() => ({ pending: null, error: null }));
  let active = false;
  let current: { readonly scope: string; readonly abort: AbortController } | null = null;
  function cancel() {
    const previous = current; current = null;
    previous?.abort.abort();
  }
  return {
    store,
    activate() { cancel(); active = true; store.setState({ pending: null, error: null }); },
    deactivate() { active = false; cancel(); },
    cancel() { cancel(); store.setState({ pending: null }); },
    async run<T>(id: string, operation: (signal: AbortSignal) => T | Promise<T>, consume?: (value: T) => void, options?: { pendingForAsyncOnly?: boolean }): Promise<boolean> {
      if (!active) return false;
      cancel();
      const request = { scope: currentScope(), abort: new AbortController() };
      current = request;
      const valid = () => active && current === request && request.scope === currentScope();
      if (options?.pendingForAsyncOnly) store.setState({ error: null });
      else store.setState({ pending: id, error: null });
      try {
        if (!valid()) return false;
        const result = operation(request.abort.signal);
        let value: T;
        if (options?.pendingForAsyncOnly) {
          if (result && typeof (result as Promise<T>).then === 'function') {
            // A synchronous acknowledgement or already-resolved promise must not
            // disable (and blur) the focused control between keyboard commands.
            let settled = false;
            const completion = Promise.resolve(result).then(value => { settled = true; return value; }, error => { settled = true; throw error; });
            void Promise.resolve().then(() => { if (!settled && valid()) store.setState({ pending: id, error: null }); });
            value = await completion;
          } else value = result as T;
        } else value = await result;
        if (!valid()) return false;
        consume?.(value);
        if (!valid()) return false;
        store.setState({ pending: null });
        return true;
      } catch (error) {
        if (!valid()) return false;
        store.setState({ pending: null, error: error instanceof Error ? error.message : String(error) });
        return false;
      } finally { if (current === request) current = null; }
    },
  };
}

import { useLayoutEffect, useRef } from "react";
import { useStore } from "zustand";
import { createActionOwner } from "@/components/nyc-tron/ui/components/shell/action-owner";

/** Cancel stale requests at the committed document boundary, before new controls accept input. */
export function useOwnedAction(scope: string) {
  const committed = useRef(scope);
  const ref = useRef<ReturnType<typeof createActionOwner> | null>(null);
  ref.current ??= createActionOwner(() => committed.current);
  const owner = ref.current;
  useLayoutEffect(() => {
    committed.current = scope;
    owner.activate();
    return () => owner.deactivate();
  }, [owner, scope]);
  const state = useStore(owner.store, value => value);
  const run: typeof owner.run = (id, operation, consume, options) => committed.current === scope ? owner.run(id, operation, consume, options) : Promise.resolve(false);
  return { ...state, run, cancel: owner.cancel };
}

/**
 * Tailwind classes are merged at the APP boundary. Joining without
 * tailwind-merge avoids deleting custom typography/color utilities that
 * depend on each consumer's own @theme configuration.
 */
export function joinClasses(...items: Array<string|false|null|undefined>):string {
  return items.filter(Boolean).join(" ");
}
